<main class="auth-shell"><section class="card auth-card"><div class="auth-intro"><span class="eyebrow">Registrierung ab 18 Jahren</span><h1>Verkäuferinnen-Konto erstellen</h1><p class="muted">Nach der Registrierung bestätigst du deine E-Mail-Adresse. Danach kannst du verfügbare Angebote annehmen.</p></div><?php if($errors):?><div class="alert danger"><ul><?php foreach($errors as $e):?><li><?=App\Core\View::e($e)?></li><?php endforeach;?></ul></div><?php endif;?><form method="post" class="form-grid"><?=App\Core\Csrf::field()?>
<h3 class="full">Persönliche Angaben</h3><label>Vorname<input name="first_name" value="<?=App\Core\View::e($_POST['first_name']??'')?>" autocomplete="given-name" required></label><label>Nachname<input name="last_name" value="<?=App\Core\View::e($_POST['last_name']??'')?>" autocomplete="family-name" required></label><label>Geburtsdatum<input name="birth_date" type="date" value="<?=App\Core\View::e($_POST['birth_date']??'')?>" required></label><label>Telefonnummer<input name="phone" value="<?=App\Core\View::e($_POST['phone']??'')?>" autocomplete="tel" required></label>
<h3 class="full">Adresse</h3><label class="full">Straße und Hausnummer<input name="street" value="<?=App\Core\View::e($_POST['street']??'')?>" autocomplete="street-address" required></label><label>PLZ<input name="postal_code" value="<?=App\Core\View::e($_POST['postal_code']??'')?>" autocomplete="postal-code" required></label><label>Ort<input name="city" value="<?=App\Core\View::e($_POST['city']??'')?>" autocomplete="address-level2" required></label>
<h3 class="full">Zugangsdaten</h3><label class="full">E-Mail-Adresse<input name="email" type="email" value="<?=App\Core\View::e($_POST['email']??'')?>" autocomplete="email" required></label><label class="full">Passwort<input name="password" type="password" minlength="10" autocomplete="new-password" required><small class="field-help">Mindestens 10 Zeichen.</small></label>
<div class="full consent-list"><h3>Bestätigungen</h3><?php $checks=['adult_confirm'=>'Ich bestätige, mindestens 18 Jahre alt zu sein.','terms'=>'Ich akzeptiere die Plattformbedingungen.','privacy'=>'Ich habe die Datenschutzhinweise gelesen.','content_rules'=>'Ich akzeptiere die Inhaltsregeln.','evidence_rules'=>'Ich akzeptiere die Nachweisregeln.','shipping_rules'=>'Ich akzeptiere die Versandregeln.','wallet_rules'=>'Ich akzeptiere die Wallet- und Auszahlungsbedingungen.'];foreach($checks as $n=>$t):?><label class="check"><input type="checkbox" name="<?=$n?>" value="1" <?=isset($_POST[$n])?'checked':''?> required><span><?=App\Core\View::e($t)?></span></label><?php endforeach;?></div><button class="btn primary full" type="submit">Konto erstellen</button></form><p class="muted" style="text-align:center;margin-top:18px">Bereits registriert? <a href="/login"><strong>Anmelden</strong></a></p></section></main>